
function createTableRow ( eng, transcript ) {
	var arr_eng = eng.split(' ');
	var arr_transcript = transcript.split(' ');
	var output = '';
	
	arr_eng.forEach( function ( item, i, arr ) {
		var eng_word = arr_eng[i];
		var transcript_word = arr_transcript[i];
		output += '<span class="tooltip">' + eng_word + '<span class="tooltiptext">' + transcript_word + '</span></span> ';
	} );
	
	return output;
}
  
  
function handleArr () {
	var output = '';
	arr.forEach( function ( item ) {
		var eng = item.e;
		var trns = item.t;
		var rus = item.r;
		
		var outputRow = '<tr><td>' + createTableRow ( eng, trns ) + '</td><td>' + rus + '</td></tr>';
		output += outputRow;
		
	} );
	
	return output;
}


